import {MAX_BYTES,CSVError,decodeBytes,detectDelimiter,parseCSV,diagnose,exportCSV} from './core.js';
import {catalog} from './locales.js';
const $=id=>document.getElementById(id),lang=document.documentElement.lang,t=catalog[lang]||catalog.ko;let original=null,originalName='',parsed=null,issues=[],fileVersion=0;
document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t[e.dataset.t]);$('raw').placeholder=t.paste;$('language').value=lang;$('language').onchange=e=>location.href=new URL(e.target.value==='ko'?'./':e.target.value+'/',document.baseURI).href;
const status=(message,error=false)=>{$('status').textContent=message;$('status').className=error?'error':'';};
function invalidate(){parsed=null;issues=[];$('normalize').disabled=true;$('errors').disabled=true;for(const id of ['records','columns','issues'])$(id).textContent='0';$('issueList').replaceChildren();const td=document.createElement('td');td.className='empty';td.textContent=t.noResult;const tr=document.createElement('tr');tr.append(td);const body=document.createElement('tbody');body.append(tr);$('table').replaceChildren(body);}
function changed(){invalidate();status(t.changed);}
function decodeSelected(){if(!original)return;invalidate();try{$('raw').value=decodeBytes(original,$('encoding').value);status(t.loaded+($('raw').value.includes('\uFFFD')?' '+t.replacement:''));}catch(e){$('raw').value='';status(t[e.message]||t.readError,true);}}
$('encoding').onchange=decodeSelected;
$('file').onchange=async e=>{const version=++fileVersion,file=e.target.files[0];if(!file)return;invalidate();try{if(file.size>MAX_BYTES)throw new CSVError('tooLarge');const bytes=new Uint8Array(await file.arrayBuffer());if(version!==fileVersion)return;original=bytes;originalName=file.name;$('original').disabled=false;decodeSelected();const frag=document.createDocumentFragment();for(const encoding of ['utf-8','euc-kr','utf-16le','utf-16be','windows-1252']){const section=document.createElement('div');section.className='candidate';const strong=document.createElement('strong');strong.textContent=encoding;const pre=document.createElement('pre');try{pre.textContent=decodeBytes(bytes,encoding).slice(0,160);}catch{pre.textContent=t.decodeError;pre.className='invalid';}section.append(strong,pre);frag.append(section);}$('candidates').replaceChildren(frag);$('candidatePanel').hidden=false;}catch(e){if(version!==fileVersion)return;original=null;originalName='';$('raw').value='';$('original').disabled=true;$('candidatePanel').hidden=true;status(t[e.message]||t.readError,true);}};
$('raw').addEventListener('input',changed);$('delimiter').onchange=changed;$('expected').oninput=changed;
$('clear').onclick=()=>{fileVersion++;original=null;originalName='';$('file').value='';$('raw').value='';$('expected').value='';$('original').disabled=true;$('candidatePanel').hidden=true;invalidate();status(t.cleared);};
$('example').onclick=()=>{fileVersion++;original=null;originalName='';$('file').value='';$('original').disabled=true;$('candidatePanel').hidden=true;$('raw').value='id,name,note,amount\r\n001,"Sample, A","Line 1\nLine 2",9007199254740993\r\n002,"Sample ""B""",2026-01-15,00042\r\n003,Uneven,record\r\n';$('delimiter').value='auto';$('expected').value='';inspect();};
function inspect(){invalidate();try{const value=$('delimiter').value,d=value==='auto'?detectDelimiter($('raw').value):value==='tab'?'\t':value==='pipe'?'|':value;const result=parseCSV($('raw').value,d);const expected=$('expected').value===''?result.rows[0].length:Number($('expected').value);const problem=diagnose(result,expected);parsed=result;issues=problem;$('records').textContent=result.rows.length.toLocaleString(lang);$('columns').textContent=String(expected);$('issues').textContent=String(problem.length);$('normalize').disabled=false;$('errors').disabled=!problem.length;const fragment=document.createDocumentFragment();const head=document.createElement('thead'),hr=document.createElement('tr');for(const x of [t.record,t.line,...Array.from({length:Math.max(...result.rows.slice(0,100).map(r=>r.length))},(_,i)=>String(i+1))]){const th=document.createElement('th');th.textContent=x;hr.append(th);}head.append(hr);fragment.append(head);const body=document.createElement('tbody');result.rows.slice(0,100).forEach((row,i)=>{const tr=document.createElement('tr');if(row.length!==expected)tr.className='uneven';for(const x of [String(i+1),String(result.lines[i]),...row]){const td=document.createElement('td');td.textContent=x.length>160?x.slice(0,160)+'…':x;td.title=x;tr.append(td);}body.append(tr);});fragment.append(body);$('table').replaceChildren(fragment);if(problem.length){const p=document.createElement('p');p.className='issue-note';p.textContent=t.mismatch;$('issueList').append(p);const list=document.createElement('ul');for(const r of problem.slice(0,20)){const li=document.createElement('li');li.textContent=`${t.record} ${r.record} · ${t.line} ${r.line} · ${t.actual}: ${r.actual} / ${r.expected}`;list.append(li);}$('issueList').append(list);}const label=d==='\t'?t.tab:d==='|'?t.pipe:d===';'?t.semicolon:t.comma;status(`${t.ok} · ${t.delimiter}: ${label}${$('raw').value.includes('\uFFFD')?' · '+t.replacement:''}`);}catch(e){status(`${t[e.message]||t.readError}${e.line?' · '+t.line+' '+e.line:''}`,true);}}
$('inspect').onclick=inspect;
function download(bytes,type,name){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('original').onclick=()=>{if(original)download(original,'application/octet-stream',originalName||'original.csv');};
$('normalize').onclick=()=>{if(parsed)download(exportCSV(parsed.rows,{safe:$('safe').checked}),'text/csv;charset=utf-8','normalized.csv');};
$('errors').onclick=()=>download(exportCSV([[t.record,t.line,t.actual,t.columns],...issues.map(r=>[r.record,r.line,r.actual,r.expected])]),'text/csv;charset=utf-8','csv-issues.csv');
